employee_models_replacement = """model EmployeeProfile {\n  tenantId          String                 @default(\"tenant_pagsibol4b_default\")\n  id                String                 @id @default(cuid())\n  userId            String?                @unique\n  user              User?                  @relation(\"EmployeeUser\", fields: [userId], references: [id], onDelete: SetNull)\n  employeeNumber    String\n  name              String\n  position          String\n  email             String?\n  phone             String\n  address           String\n  hireDate          DateTime               @db.Date\n  salaryType        SalaryType\n  baseRate          Decimal                @db.Decimal(12, 2)\n  standardWorkDays  Int                    @default(26)\n  fixedAllowance    Decimal                @default(0) @db.Decimal(12, 2)\n  fixedDeduction    Decimal                @default(0) @db.Decimal(12, 2)\n  status            EmployeeStatus         @default(ACTIVE)\n  compensations     EmployeeCompensation[]\n  attendance        Attendance[]\n  schedules         EmployeeSchedule[]\n  payslips          Payslip[]\n  payrollDeductions PayrollDeduction[]\n  employeeLoans     EmployeeLoan[]\n  overtimeRecords   OvertimeRecord[]\n  createdAt         DateTime               @default(now())\n  updatedAt         DateTime               @updatedAt\n\n  @@unique([tenantId, employeeNumber])\n  @@index([name])\n  @@index([status])\n  @@index([tenantId])\n}\n\nmodel EmployeeCompensation {\n  tenantId           String            @default(\"tenant_pagsibol4b_default\")\n  id                 String            @id @default(cuid())\n  employeeId         String\n  employee           EmployeeProfile   @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  effectiveFrom      DateTime          @db.Date\n  effectiveTo        DateTime?         @db.Date\n  compensationBasis  CompensationBasis\n  payFrequency       PayFrequency      @default(SEMI_MONTHLY)\n  attendancePolicy   AttendancePolicy  @default(REQUIRED)\n  rate               Decimal           @db.Decimal(12, 2)\n  standardWorkDays   Int               @default(26)\n  standardHoursPerDay Decimal          @default(8) @db.Decimal(5, 2)\n  fixedAllowance     Decimal           @default(0) @db.Decimal(12, 2)\n  fixedDeduction     Decimal           @default(0) @db.Decimal(12, 2)\n  createdById        String?\n  createdBy          User?             @relation(\"EmployeeCompensationCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n  payslips           Payslip[]\n  createdAt          DateTime          @default(now())\n  updatedAt          DateTime          @updatedAt\n\n  @@unique([tenantId, employeeId, effectiveFrom])\n  @@index([tenantId, employeeId, effectiveFrom, effectiveTo])\n  @@index([createdById])\n}\n"""

