write(
    "components/employee-form.tsx",
    '''import { AttendancePolicy, CompensationBasis, PayFrequency, Role, type EmployeeCompensation, type EmployeeProfile } from "@prisma/client";\nimport Link from "next/link";\nimport { saveEmployeeAction } from "@/lib/actions/employees";\nimport { SubmitButton } from "@/components/ui";\nimport { PasswordInput } from "@/components/password-input";\nimport { inputDate } from "@/lib/utils";\nimport { roleLabelMap } from "@/lib/tenant-role-access";\n\nconst primaryRoleOptions = [\n  Role.HOA_ADMIN,\n  Role.BILLING_MANAGER,\n  Role.PAYROLL_MANAGER,\n  Role.STAFF,\n  Role.ADMIN,\n  Role.EMPLOYEE,\n] as const;\n\ntype EmployeeWithPayrollConfiguration = EmployeeProfile & {\n  user?: { email: string; role: Role } | null;\n  compensations?: EmployeeCompensation[];\n};\n\nexport function EmployeeForm({ employee }: { employee?: EmployeeWithPayrollConfiguration }) {\n  const compensation = employee?.compensations?.[0];\n  const defaultBasis = compensation?.compensationBasis\n    ?? (employee?.salaryType === "DAILY" ? CompensationBasis.DAILY : CompensationBasis.MONTHLY);\n\n  return (\n    <form action={saveEmployeeAction} className="card max-w-4xl space-y-6">\n      {employee && <input type="hidden" name="id" value={employee.id} />}\n\n      <div>\n        <h2 className="text-lg font-black">Employee information</h2>\n        <p className="text-sm text-slate-500">Employment details used for attendance and payroll calculations.</p>\n      </div>\n\n      <div className="grid gap-4 sm:grid-cols-2">\n        <Field label="Employee number" name="employeeNumber" defaultValue={employee?.employeeNumber} required />\n        <Field label="Full name" name="name" defaultValue={employee?.name} required />\n        <Field label="Position" name="position" defaultValue={employee?.position} required />\n        <Field label="Phone" name="phone" type="tel" defaultValue={employee?.phone} required />\n        <Field label="Email" name="email" type="email" defaultValue={employee?.email ?? ""} />\n        <Field label="Hire date" name="hireDate" type="date" defaultValue={employee ? inputDate(employee.hireDate) : inputDate(new Date())} required />\n        <div className="sm:col-span-2">\n          <Field label="Address" name="address" defaultValue={employee?.address} required />\n        </div>\n      </div>\n\n      <div className="border-t border-slate-100 pt-6">\n        <h2 className="text-lg font-black">Payroll configuration</h2>\n        <p className="text-sm text-slate-500">Compensation basis, pay frequency and attendance policy are independent and effective-dated. Changing payroll terms creates a new version instead of rewriting prior payroll history.</p>\n      </div>\n\n      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">\n        <div>\n          <label className="label">Compensation basis</label>\n          <select className="field" name="compensationBasis" defaultValue={defaultBasis}>\n            <option value={CompensationBasis.MONTHLY}>Monthly salary</option>\n            <option value={CompensationBasis.DAILY}>Daily rate</option>\n            <option value={CompensationBasis.HOURLY}>Hourly rate</option>\n            <option value={CompensationBasis.FIXED_PER_PERIOD}>Fixed per payroll period</option>\n          </select>\n        </div>\n        <div>\n          <label className="label">Pay frequency</label>\n          <select className="field" name="payFrequency" defaultValue={compensation?.payFrequency ?? PayFrequency.SEMI_MONTHLY}>\n            <option value={PayFrequency.SEMI_MONTHLY}>Semi-monthly</option>\n            <option value={PayFrequency.MONTHLY}>Monthly</option>\n          </select>\n        </div>\n        <div>\n          <label className="label">Attendance policy</label>\n          <select className="field" name="attendancePolicy" defaultValue={compensation?.attendancePolicy ?? AttendancePolicy.REQUIRED}>\n            <option value={AttendancePolicy.REQUIRED}>Attendance required</option>\n            <option value={AttendancePolicy.EXCEPTION_ONLY}>Exception only</option>\n            <option value={AttendancePolicy.NOT_REQUIRED}>No clock required</option>\n          </select>\n        </div>\n        <Field label="Effective from" name="compensationEffectiveFrom" type="date" defaultValue={inputDate(new Date())} required />\n        <Field label="Rate (PHP)" name="rate" type="number" min="0.01" step="0.01" defaultValue={compensation ? String(compensation.rate) : employee ? String(employee.baseRate) : "18000"} required />\n        <Field label="Standard workdays / month" name="standardWorkDays" type="number" min="1" max="31" defaultValue={compensation?.standardWorkDays ?? employee?.standardWorkDays ?? 26} required />\n        <Field label="Standard hours / day" name="standardHoursPerDay" type="number" min="0.01" max="24" step="0.01" defaultValue={compensation ? String(compensation.standardHoursPerDay) : "8"} required />\n        <Field label="Fixed allowance" name="fixedAllowance" type="number" min="0" step="0.01" defaultValue={compensation ? String(compensation.fixedAllowance) : employee ? String(employee.fixedAllowance) : "0"} required />\n        <Field label="Fixed deduction" name="fixedDeduction" type="number" min="0" step="0.01" defaultValue={compensation ? String(compensation.fixedDeduction) : employee ? String(employee.fixedDeduction) : "0"} required />\n        <div>\n          <label className="label">Status</label>\n          <select className="field" name="status" defaultValue={employee?.status ?? "ACTIVE"}>\n            <option value="ACTIVE">Active</option>\n            <option value="INACTIVE">Inactive</option>\n          </select>\n        </div>\n      </div>\n\n      <div className="rounded-xl bg-amber-50 p-3 text-sm font-semibold text-amber-800">\n        For Daily or Hourly compensation, Attendance Required is mandatory. Backdated payroll-term changes are blocked when they would overlap finalized or paid payroll.\n      </div>\n\n      <div className="border-t border-slate-100 pt-6">\n        <h2 className="text-lg font-black">Primary tenant role</h2>\n        <p className="text-sm text-slate-500">Version 1.0 supports one primary role per user. Select the role that controls system access.</p>\n      </div>\n\n      <div>\n        <label className="label">Primary role</label>\n        <select className="field" name="primaryRole" defaultValue={employee?.user?.role ?? Role.EMPLOYEE}>\n          {primaryRoleOptions.map((role) => (\n            <option key={role} value={role}>{roleLabelMap[role] ?? role.replaceAll("_", " ")}</option>\n          ))}\n        </select>\n      </div>\n\n      <div className="border-t border-slate-100 pt-6">\n        <h2 className="text-lg font-black">Login access</h2>\n        <p className="text-sm text-slate-500">Enable login so this employee can access the system using the selected primary role.</p>\n      </div>\n\n      <div className="grid gap-4 sm:grid-cols-2">\n        <label className="flex items-center gap-2 rounded-xl bg-slate-50 p-3 text-sm font-bold">\n          <input type="checkbox" name="createEmployeeLogin" defaultChecked={Boolean(employee?.userId)} className="accent-pine-600" />\n          Enable login account\n        </label>\n        <Field label="Login email" name="loginEmail" type="email" defaultValue={employee?.user?.email ?? employee?.email ?? ""} />\n        <Field label="Temporary password" name="loginPassword" type="password" defaultValue="ChangeMe123!" autoComplete="new-password" />\n        {employee?.userId && (\n          <p className="rounded-xl bg-emerald-50 p-3 text-sm font-semibold text-emerald-700">Login account is linked. Keep login enabled to synchronize this user&apos;s role.</p>\n        )}\n      </div>\n\n      <div className="flex flex-wrap gap-3 border-t border-slate-100 pt-5">\n        <SubmitButton>{employee ? "Save changes" : "Create employee"}</SubmitButton>\n        <Link className="btn-secondary" href="/admin/employees">Cancel</Link>\n      </div>\n    </form>\n  );\n}\n\nfunction Field({ label, name, ...props }: React.InputHTMLAttributes<HTMLInputElement> & { label: string; name: string }) {\n  return (\n    <div>\n      <label className="label" htmlFor={name}>{label}</label>\n      {props.type === "password" ? <PasswordInput id={name} name={name} {...props} /> : <input className="field" id={name} name={name} {...props} />}\n    </div>\n  );\n}\n''',
)

write(
    "app/admin/employees/[id]/page.tsx",
    '''import { notFound } from "next/navigation";\nimport { EmployeeForm } from "@/components/employee-form";\nimport { PageHeader } from "@/components/page-header";\nimport { DeleteButton } from "@/components/ui";\nimport { deleteEmployeeAction } from "@/lib/actions/employees";\nimport { prisma } from "@/lib/db";\nimport { requirePayrollAccess } from "@/lib/payroll-access";\n\nfunction money(value: unknown) {\n  return Number(value).toLocaleString("en-PH", { style: "currency", currency: "PHP" });\n}\n\nfunction dateLabel(value: Date | null) {\n  return value ? value.toLocaleDateString("en-PH", { timeZone: "UTC" }) : "Open-ended";\n}\n\nexport default async function EditEmployeePage({ params }: { params: Promise<{ id: string }> }) {\n  const { user } = await requirePayrollAccess();\n  const { id } = await params;\n  const employee = await prisma.employeeProfile.findFirst({\n    where: { id, tenantId: user.tenantId },\n    include: {\n      user: true,\n      compensations: {\n        where: { tenantId: user.tenantId },\n        include: { createdBy: { select: { name: true } } },\n        orderBy: { effectiveFrom: "desc" },\n      },\n    },\n  });\n  if (!employee) notFound();\n\n  return (\n    <>\n      <PageHeader\n        eyebrow="Employees"\n        title={employee.name}\n        description={`${employee.employeeNumber} · ${employee.position}`}\n        action={<form action={deleteEmployeeAction}><input type="hidden" name="id" value={employee.id} /><DeleteButton label="Delete employee" /></form>}\n      />\n      <EmployeeForm employee={employee} />\n\n      <section className="card mt-6 max-w-4xl overflow-hidden">\n        <div className="mb-4">\n          <h2 className="text-lg font-black">Payroll configuration history</h2>\n          <p className="text-sm text-slate-500">Effective-dated versions are retained for audit and payroll reproducibility. Existing versions are not overwritten when payroll terms change.</p>\n        </div>\n        {employee.compensations.length ? (\n          <div className="overflow-x-auto">\n            <table className="min-w-full text-sm">\n              <thead className="text-left text-xs uppercase tracking-wide text-slate-500">\n                <tr>\n                  <th className="px-3 py-2">Effective</th>\n                  <th className="px-3 py-2">Basis / frequency</th>\n                  <th className="px-3 py-2">Attendance</th>\n                  <th className="px-3 py-2">Rate</th>\n                  <th className="px-3 py-2">Created by</th>\n                </tr>\n              </thead>\n              <tbody className="divide-y divide-slate-100">\n                {employee.compensations.map((item) => (\n                  <tr key={item.id}>\n                    <td className="px-3 py-3 font-semibold">{dateLabel(item.effectiveFrom)} → {dateLabel(item.effectiveTo)}</td>\n                    <td className="px-3 py-3">{item.compensationBasis.replaceAll("_", " ")} · {item.payFrequency.replaceAll("_", " ")}</td>\n                    <td className="px-3 py-3">{item.attendancePolicy.replaceAll("_", " ")}</td>\n                    <td className="px-3 py-3 font-bold">{money(item.rate)}</td>\n                    <td className="px-3 py-3">{item.createdBy?.name ?? "Legacy migration"}</td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        ) : (\n          <p className="text-sm text-slate-500">No effective-dated payroll configuration exists yet.</p>\n        )}\n      </section>\n    </>\n  );\n}\n''',
)


# -----------------------------------------------------------------------------
# Payroll run: resolve config as of coverage end and snapshot it on each payslip
# -----------------------------------------------------------------------------
payroll_actions_path = "lib/actions/payroll.ts"
payroll_actions = read(payroll_actions_path)
old_refresh = '''/**\n * @requirement PAY-SEC-001 PAY-CALC-001 PAY-ATT-001 PAY-OT-001\n * @status IMPLEMENTED\n */\nasync function refreshPeriodPayslips(tx: Prisma.TransactionClient, period: { id: string; tenantId: string; startDate: Date; endDate: Date }) {\n  const employees = await tx.employeeProfile.findMany({\n    where: { tenantId: period.tenantId, status: "ACTIVE", hireDate: { lte: period.endDate } },\n    include: { attendance: { where: { tenantId: period.tenantId, date: { gte: period.startDate, lte: period.endDate } } } },\n  });\n  const assignedDeductions = await tx.payrollDeduction.findMany({\n    where: { tenantId: period.tenantId, payrollId: period.id },\n    select: { employeeId: true, amount: true },\n  });\n  const approvedOvertime = await tx.overtimeRecord.findMany({\n    where: { tenantId: period.tenantId, status: OvertimeStatus.APPROVED, date: { gte: period.startDate, lte: period.endDate } },\n    select: { employeeId: true, hours: true, source: true },\n  });\n  const deductionsByEmployee = new Map<string, { amount: Prisma.Decimal }[]>();\n  for (const deduction of assignedDeductions) {\n    const employeeDeductions = deductionsByEmployee.get(deduction.employeeId) ?? [];\n    employeeDeductions.push({ amount: deduction.amount });\n    deductionsByEmployee.set(deduction.employeeId, employeeDeductions);\n  }\n  const overtimeByEmployee = new Map<string, { hours: Prisma.Decimal; source: OvertimeSource }[]>();\n  for (const overtime of approvedOvertime) {\n    const employeeOvertime = overtimeByEmployee.get(overtime.employeeId) ?? [];\n    employeeOvertime.push({ hours: overtime.hours, source: overtime.source });\n    overtimeByEmployee.set(overtime.employeeId, employeeOvertime);\n  }\n  const activeIds = employees.map((employee) => employee.id);\n  await tx.payslip.deleteMany({ where: { tenantId: period.tenantId, payrollId: period.id, ...(activeIds.length ? { employeeId: { notIn: activeIds } } : {}) } });\n  for (const employee of employees) {\n    const values = calculatePayslip(employee, employee.attendance, deductionsByEmployee.get(employee.id) ?? [], overtimeByEmployee.get(employee.id) ?? []);\n    await tx.payslip.upsert({\n      where: { payrollId_employeeId: { payrollId: period.id, employeeId: employee.id } },\n      create: { tenantId: period.tenantId, payrollId: period.id, employeeId: employee.id, ...values },\n      update: values,\n    });\n  }\n}\n'''
new_refresh = '''/**\n * @requirement PAY-SEC-001 PAY-CALC-001 PAY-ATT-001 PAY-OT-001 PAY-COMP-002 PAY-COMP-003\n * @status IMPLEMENTED\n * @description Resolve the employee payroll configuration effective on the cutoff end date and persist an immutable configuration snapshot on the payslip.\n */\nasync function refreshPeriodPayslips(tx: Prisma.TransactionClient, period: { id: string; tenantId: string; startDate: Date; endDate: Date }) {\n  const employees = await tx.employeeProfile.findMany({\n    where: { tenantId: period.tenantId, status: "ACTIVE", hireDate: { lte: period.endDate } },\n    include: {\n      attendance: { where: { tenantId: period.tenantId, date: { gte: period.startDate, lte: period.endDate } } },\n      compensations: {\n        where: {\n          tenantId: period.tenantId,\n          effectiveFrom: { lte: period.endDate },\n          OR: [{ effectiveTo: null }, { effectiveTo: { gte: period.endDate } }],\n        },\n        orderBy: { effectiveFrom: "desc" },\n        take: 1,\n      },\n    },\n  });\n  const assignedDeductions = await tx.payrollDeduction.findMany({\n    where: { tenantId: period.tenantId, payrollId: period.id },\n    select: { employeeId: true, amount: true },\n  });\n  const approvedOvertime = await tx.overtimeRecord.findMany({\n    where: { tenantId: period.tenantId, status: OvertimeStatus.APPROVED, date: { gte: period.startDate, lte: period.endDate } },\n    select: { employeeId: true, hours: true, source: true },\n  });\n  const deductionsByEmployee = new Map<string, { amount: Prisma.Decimal }[]>();\n  for (const deduction of assignedDeductions) {\n    const employeeDeductions = deductionsByEmployee.get(deduction.employeeId) ?? [];\n    employeeDeductions.push({ amount: deduction.amount });\n    deductionsByEmployee.set(deduction.employeeId, employeeDeductions);\n  }\n  const overtimeByEmployee = new Map<string, { hours: Prisma.Decimal; source: OvertimeSource }[]>();\n  for (const overtime of approvedOvertime) {\n    const employeeOvertime = overtimeByEmployee.get(overtime.employeeId) ?? [];\n    employeeOvertime.push({ hours: overtime.hours, source: overtime.source });\n    overtimeByEmployee.set(overtime.employeeId, employeeOvertime);\n  }\n  const activeIds = employees.map((employee) => employee.id);\n  await tx.payslip.deleteMany({ where: { tenantId: period.tenantId, payrollId: period.id, ...(activeIds.length ? { employeeId: { notIn: activeIds } } : {}) } });\n\n  for (const employee of employees) {\n    const compensation = employee.compensations[0];\n    const payrollEmployee = compensation ? {\n      compensationBasis: compensation.compensationBasis,\n      payFrequency: compensation.payFrequency,\n      attendancePolicy: compensation.attendancePolicy,\n      rate: compensation.rate,\n      standardWorkDays: compensation.standardWorkDays,\n      standardHoursPerDay: compensation.standardHoursPerDay,\n      fixedAllowance: compensation.fixedAllowance,\n      fixedDeduction: compensation.fixedDeduction,\n    } : employee;\n\n    const values = calculatePayslip(\n      payrollEmployee,\n      employee.attendance,\n      deductionsByEmployee.get(employee.id) ?? [],\n      overtimeByEmployee.get(employee.id) ?? [],\n    );\n    const compensationSnapshot = compensation ? {\n      source: "EMPLOYEE_COMPENSATION",\n      compensationId: compensation.id,\n      resolvedForDate: period.endDate.toISOString(),\n      effectiveFrom: compensation.effectiveFrom.toISOString(),\n      effectiveTo: compensation.effectiveTo?.toISOString() ?? null,\n      compensationBasis: compensation.compensationBasis,\n      payFrequency: compensation.payFrequency,\n      attendancePolicy: compensation.attendancePolicy,\n      rate: compensation.rate.toString(),\n      standardWorkDays: compensation.standardWorkDays,\n      standardHoursPerDay: compensation.standardHoursPerDay.toString(),\n      fixedAllowance: compensation.fixedAllowance.toString(),\n      fixedDeduction: compensation.fixedDeduction.toString(),\n    } : {\n      source: "LEGACY_EMPLOYEE_PROFILE",\n      resolvedForDate: period.endDate.toISOString(),\n      salaryType: employee.salaryType,\n      baseRate: employee.baseRate.toString(),\n      standardWorkDays: employee.standardWorkDays,\n      fixedAllowance: employee.fixedAllowance.toString(),\n      fixedDeduction: employee.fixedDeduction.toString(),\n    };\n    const payslipValues = { ...values, compensationId: compensation?.id ?? null, compensationSnapshot };\n\n    await tx.payslip.upsert({\n      where: { payrollId_employeeId: { payrollId: period.id, employeeId: employee.id } },\n      create: { tenantId: period.tenantId, payrollId: period.id, employeeId: employee.id, ...payslipValues },\n      update: payslipValues,\n    });\n  }\n}\n'''
payroll_actions = replace_once(payroll_actions, old_refresh, new_refresh, "payroll effective compensation resolver")
write(payroll_actions_path, payroll_actions)


